     6→class ShortThreadConverter : ClassicConverter() {
     7→    override fun convert(event: ILoggingEvent): String {
     8→        val threadName = event.threadName
     9→        val maxLength = 20
    10→
    11→        return if (threadName.length > maxLength) {
    12→            "...${threadName.takeLast(maxLength)}"
    13→        } else {
    14→            threadName
    15→        }
    16→    }
    17→}
